<script setup lang="ts">
import type { Evaluation } from '../types'
import { statusName } from '../format'
import MoneyValue from './MoneyValue.vue'
defineProps<{ evaluation: Evaluation }>()
const scenarioName: Record<string, string> = { low: '低', base: '基准', high: '高' }
const checkName: Record<string, string> = { pass: '通过', fail: '未通过', unknown: '待补数据' }
</script>
<template>
  <section class="evaluation-section" aria-label="方案评估结果"><div class="section-head"><h2>情景比较</h2><span class="badge" :class="evaluation.feasibility === 'checks_passed' ? 'success' : 'warning'">{{ statusName(evaluation.feasibility) }}</span></div>
    <ul v-if="evaluation.issues.length" class="issue-list"><li v-for="(issue, i) in evaluation.issues" :key="i">{{ issue }}</li></ul>
    <div class="table-scroll"><table><thead><tr><th>候选 / 情景</th><th class="number">收入</th><th class="number">毛利润</th><th class="number">贡献利润</th><th class="number">预算占用</th><th class="number">件数</th><th>规则</th></tr></thead><tbody><template v-for="candidate in evaluation.candidates" :key="candidate.id"><tr v-for="(calculation, scenario) in candidate.scenarios" :key="`${candidate.id}-${scenario}`" :class="{ selected: candidate.id === evaluation.selected_candidate }"><td><strong>{{ candidate.label }} <span v-if="candidate.id === evaluation.selected_candidate" class="muted">· 已选</span></strong><small>{{ scenarioName[String(scenario)] ?? scenario }}</small></td><td class="number"><MoneyValue :value="calculation.revenue_minor" /></td><td class="number"><MoneyValue :value="calculation.gross_profit_minor" /></td><td class="number"><MoneyValue :value="calculation.contribution_profit_minor" /></td><td class="number"><MoneyValue :value="calculation.budget_used_minor" /></td><td class="number">{{ calculation.units }}</td><td>{{ candidate.rule_supported ? '支持测算规则' : '无执行支持' }}<details v-if="calculation.checks.length"><summary>约束 {{ calculation.checks.length }} 项</summary><ul class="check-list"><li v-for="check in calculation.checks" :key="check.code"><span class="status-word" :class="check.status">{{ checkName[check.status] }}</span> {{ check.label }}<small>{{ check.reason }}</small></li></ul></details></td></tr></template></tbody></table></div>
    <template v-for="candidate in evaluation.candidates" :key="`capacity-${candidate.id}`"><details v-if="candidate.scenarios.high?.resources?.length" :open="candidate.id === evaluation.selected_candidate"><summary>{{ candidate.label }} · 高情景岗位风险</summary><div class="table-scroll"><table><thead><tr><th>岗位</th><th class="number">需要工时</th><th class="number">可用工时</th><th class="number">缺口工时</th><th class="number">需增人数</th></tr></thead><tbody><tr v-for="(resource, i) in candidate.scenarios.high.resources" :key="i"><td>{{ resource.role }}</td><td class="number">{{ resource.required_hours }}</td><td class="number">{{ resource.available_hours }}</td><td class="number">{{ resource.gap_hours }}</td><td class="number">{{ resource.additional_people }}</td></tr></tbody></table></div><ul class="check-list"><li v-for="check in candidate.scenarios.high.resource_checks ?? []" :key="check.code"><span class="status-word" :class="check.status">{{ checkName[check.status] }}</span> {{ check.label }} <span class="muted">{{ check.reason }}</span></li></ul></details></template>
    <div class="section-head"><h3>确认政策下的资源核对</h3></div><div class="table-scroll"><table><thead><tr><th>岗位</th><th class="number">需要工时</th><th class="number">可用工时</th><th class="number">缺口工时</th><th class="number">需增人数</th><th>来源</th></tr></thead><tbody><tr v-for="(resource, i) in evaluation.resources" :key="i"><td>{{ resource.role }}</td><td class="number">{{ resource.required_hours }}</td><td class="number">{{ resource.available_hours }}</td><td class="number">{{ resource.gap_hours }}</td><td class="number">{{ resource.additional_people }}</td><td>{{ resource.source }}<small>{{ resource.confirmed ? '负责人已核对' : '待核对' }}</small></td></tr></tbody></table></div>
    <div v-if="evaluation.task_checks.length" class="section-head"><h3>任务完整度</h3></div><ul class="check-list task-checks"><li v-for="check in evaluation.task_checks" :key="check.code"><span class="status-word" :class="check.status">{{ checkName[check.status] }}</span> {{ check.label }} <span class="muted">{{ check.reason }}</span></li></ul>
    <details class="lineage"><summary>查看计算依据与来源版本</summary><pre>{{ JSON.stringify(evaluation.lineage, null, 2) }}</pre></details>
  </section>
</template>
